sp_widget.client_script:
function fuaTodoController($scope, spUtil, i18n) {
	/* Based on OOB "HRJ Task Mark When Complete" controller: actions go to the server with c.server.update() */
	var c = this;
	c.completionNotes = c.data.task ? c.data.task.completion_notes : '';
	c.workNote = '';
	c.updating = false;

	c.setTaskInProgress = function() {
		submit('setTaskInProgress', i18n.getMessage('Task started'));
	};

	c.addWorkNote = function() {
		submit('addWorkNote', i18n.getMessage('Work note added'));
	};

	c.setTaskFinished = function() {
		submit('setTaskFinished', i18n.getMessage('Task completed'));
	};

	function submit(action, successMessage) {
		c.updating = true;
		c.data.action = action;
		c.data.completion_notes = c.completionNotes;
		c.data.work_note = c.workNote;
		c.server.update().then(function() {
			c.updating = false;
			c.data.action = '';
			if (!c.data.errorMessage) {
				c.workNote = '';
				c.completionNotes = c.data.task.completion_notes;
				spUtil.addInfoMessage(successMessage);
			}
		});
	}
}

sp_widget.css:
.task-activity { padding: 16px; margin-bottom: 16px; }
.fua-details { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px 24px; margin: 0; }
.fua-details dt { font-weight: normal; color: #5a6270; font-size: 12px; }
.fua-details dd { margin: 2px 0 0; }
.fua-actions { display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap; }
.fua-post { margin-top: 8px; }
.fua-required { color: #c83c36; }
.fua-notes { white-space: pre-wrap; margin: 4px 0 0; }
.fua-journal { list-style: none; padding: 0; margin: 8px 0 0; }
.fua-journal li { border-top: 1px solid #e3e6ea; padding: 8px 0; }
.fua-journal-meta { font-size: 12px; color: #5a6270; }

sp_widget.script:
(function() {
	/*
	 * Follow-up Action to-do (My tasks) - based on the OOB widget "HRJ Task Mark When Complete"
	 * (hrj-task-mark-when-complete). Same structure: resolve sys_id, handle input.action,
	 * build data.task, then data.caption / data.completed_by for the not-assigned and finished views.
	 * Changed for Follow-up Action: hr_TaskTicket is HR-Task only, so the record is read here with
	 * GlideRecordSecure (ACLs decide visibility) and updated only by its assignee. Extra fields:
	 * Action type, Due date, Request, Employee, Completion notes and Work notes.
	 */
	var TABLE = 'x_snp_manager_su_0_follow_up_action';
	var STATE_OPEN = '1', STATE_WORK_IN_PROGRESS = '2', STATE_CLOSED_COMPLETE = '3';

	data.user_id = gs.getUserID();
	data.isMobile = gs.isMobile();

	if (input && input.sys_id)
		data.sys_id = input.sys_id;
	else if (options && (options.sys_id || options.sysId))
		data.sys_id = options.sys_id || options.sysId;
	else
		data.sys_id = $sp.getValue("sys_id");
	if (!data.sys_id)
		return;

	var taskGr = new GlideRecordSecure(TABLE);
	if (!taskGr.get(data.sys_id))
		return;

	var assignedToMe = taskGr.getValue('assigned_to') == data.user_id;

	// Same action names as the HR Task widget. Like hr_TaskTicket.setTaskFinished(), the update runs
	// server-side after checking the user is the assignee: task.state and task.work_notes are
	// write-protected for itil/task_editor, which managers do not have.
	if (input && input.action && assignedToMe && taskGr.getValue('active') == '1') {
		var completionNotes = (input.completion_notes || '').trim();
		var workNote = (input.work_note || '').trim();
		var updateGr = new GlideRecord(TABLE);
		updateGr.get(data.sys_id);

		if (input.action === 'setTaskInProgress' && updateGr.getValue('state') == STATE_OPEN)
			updateGr.setValue('state', STATE_WORK_IN_PROGRESS);

		if (input.action === 'addWorkNote' && !workNote)
			data.errorMessage = gs.getMessage('Enter a work note to post.');

		if (input.action === 'setTaskFinished') {
			if (!completionNotes)
				data.errorMessage = gs.getMessage('Completion notes are required to complete the task.');
			else
				updateGr.setValue('state', STATE_CLOSED_COMPLETE);
		}

		if (!data.errorMessage) {
			if (completionNotes)
				updateGr.setValue('completion_notes', completionNotes);
			if (workNote)
				updateGr.work_notes = workNote;
			updateGr.update();
		}
		taskGr.get(data.sys_id);
	}

	data.task = getTask(taskGr);
	if (Object.keys(data.task).length == 0)
		return;

	if (!data.task.assigned_or_delegated) {
		if (data.task.finished)
			data.completed_by = data.task.assigned_to.name;
		else {
			if (gs.nil(data.task.assigned_to.userId))
				data.caption = gs.getMessage("Task is unassigned");
			else
				data.caption = gs.getMessage("Task assigned to {0}", data.task.assigned_to.name);
		}
	}

	/*
	 * Same shape as hr_TaskTicket.getTasks() returns for an HR Task, plus the Follow-up Action fields
	 */
	function getTask(gr) {
		var request = new GlideRecordSecure('x_snp_manager_su_0_manager_support_request');
		var hasRequest = request.get(gr.getValue('parent'));
		return {
			sys_id: gr.getUniqueValue(),
			number: gr.getValue('number'),
			short_description: gr.getValue('short_description'),
			description: gr.getValue('description'),
			state: gr.getValue('state'),
			stateLabel: gr.getDisplayValue('state'),
			created: gr.getDisplayValue('sys_created_on'),
			closed_at: gr.getDisplayValue('closed_at'),
			finished: gr.getValue('active') != '1',
			assigned_to: {
				userId: gr.getValue('assigned_to'),
				name: gr.getDisplayValue('assigned_to')
			},
			assigned_or_delegated: assignedToMe,
			// Follow-up Action fields
			action_type: gr.getDisplayValue('action_type'),
			due_date: gr.getDisplayValue('due_date'),
			completion_notes: gr.getValue('completion_notes') || '',
			request_number: hasRequest ? request.getValue('number') : '',
			request_summary: hasRequest ? request.getValue('short_description') : '',
			employee: hasRequest ? request.getDisplayValue('subject_person') : '',
			work_notes: getWorkNotes(gr.getUniqueValue())
		};
	}

	function getWorkNotes(sysId) {
		var notes = [];
		var journal = new GlideRecord('sys_journal_field');
		journal.addQuery('name', TABLE);
		journal.addQuery('element_id', sysId);
		journal.addQuery('element', 'work_notes');
		journal.orderByDesc('sys_created_on');
		journal.setLimit(20);
		journal.query();
		var names = {};
		while (journal.next())
			notes.push({
				value: journal.getValue('value'),
				created_by: getUserName(journal.getValue('sys_created_by'), names),
				created_on: journal.getDisplayValue('sys_created_on')
			});
		return notes;
	}

	// sys_created_by holds the user ID (login); show the person's name like the activity stream does
	function getUserName(userName, cache) {
		if (!cache[userName]) {
			var user = new GlideRecord('sys_user');
			cache[userName] = user.get('user_name', userName) ? user.getDisplayValue('name') : userName;
		}
		return cache[userName];
	}
})();
